                var logName = "LogMailSpecialDelete" + string.Format("{0:MM_dd_yyyy}", toDay) + ".html";
                var fullPath = root;
                CreateDirectory(fullPath);
                fullPath += "\\" + logFolderName;
                CreateDirectory(fullPath);
                fullPath += "\\" + logName;
                if (Directory.Exists(fullPath))
